// Scenariusz 1: @LoadBalanced RestTemplate bezposrednio (bez Gateway)
// -> round-robin miedzy 2 instancjami orders-service

// Scenariusz 2: przez Gateway (/api/v1/orders/1)
// -> stripPrefix, JWT propagowany do backendu, backend widzi /orders/1

// Scenariusz 3: bezpieczenstwo przez Gateway
// -> brak tokenu: 401, wygasly token: 401

@GetMapping("/orders/{id}")
ResponseEntity<String> getOrder(@PathVariable String id,
                                  @RequestHeader("Authorization") String authHeader) {
    if (walidujToken(authHeader) == null) return ResponseEntity.status(401).build();

    Span span = tracer.nextSpan().name("orders.get").tag("orderId", id).start();
    try (Tracer.SpanInScope scope = tracer.withSpan(span)) {
        meterRegistry.counter("orders.requests", "status", "success").increment();
        return ResponseEntity.ok("Zamowienie " + id);
    } finally {
        span.end();
    }
}

